INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Jahitan obras tidak terbentuk dengan benar', 'Jahitan overlock tidak rapat, tidak seimbang, atau tepi kain tidak terbungkus dengan baik.', 'Threading tidak benar, tegangan benang tidak seimbang, atau penyetelan looper dan jarum kurang tepat.', 'Periksa jalur threading, sesuaikan tegangan benang, dan periksa penyetelan jarum serta looper.', 'Matikan mesin dan putuskan sumber listrik sebelum memeriksa jarum atau looper.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Benang jarum sering putus', 'Benang jarum putus berulang saat proses menjahit.', 'Jarum DC×27 rusak atau bengkok, pemasangan tidak benar, jalur benang terhambat, atau tegangan terlalu tinggi.', 'Ganti jarum jika rusak, pastikan pemasangan benar, periksa jalur threading, dan sesuaikan tegangan benang.', 'Matikan mesin sebelum mengganti jarum atau memeriksa jalur benang.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Benang looper sering putus', 'Benang looper putus berulang selama proses overlock.', 'Threading looper tidak benar, tegangan benang terlalu tinggi, atau posisi looper tidak sesuai.', 'Periksa kembali jalur threading looper, sesuaikan tegangan, dan periksa posisi serta gerakan looper.', 'Matikan mesin sebelum membuka penutup dan memeriksa looper.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Jahitan obras loncat atau tidak terbentuk', 'Sebagian jahitan overlock tidak terbentuk sehingga hasil obras tidak kontinu.', 'Jarum tidak sesuai atau rusak, threading salah, atau timing jarum-looper tidak tepat.', 'Periksa kondisi dan pemasangan jarum, jalur threading, serta penyetelan jarum dan looper.', 'Matikan mesin sebelum memeriksa jarum dan mekanisme looper.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Tepi kain mengerut atau bergelombang', 'Tepi kain setelah diobras terlihat mengerut, tertarik, atau bergelombang.', 'Differential feed tidak sesuai, tekanan presser foot terlalu tinggi, atau tegangan benang tidak seimbang.', 'Sesuaikan differential feed, periksa tekanan presser foot, dan seimbangkan tegangan benang.', 'Lakukan penyetelan saat mesin berhenti dan sumber listrik dimatikan.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Lebar obras tidak sesuai', 'Lebar overedging tidak sesuai ukuran yang diinginkan atau berubah selama menjahit.', 'Penyetelan lebar obras tidak sesuai, posisi pisau atau looper kurang tepat, atau feeding tidak stabil.', 'Periksa dan sesuaikan lebar obras sesuai konfigurasi, serta periksa pisau, looper, dan feeding.', 'Matikan mesin sebelum melakukan pemeriksaan pada pisau atau komponen bergerak.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Jarum patah atau posisi jarum tidak normal', 'Jarum patah, bengkok, atau tidak bergerak pada posisi yang benar.', 'Jarum DC×27 bengkok atau salah pasang, ukuran tidak sesuai, atau terjadi kontak dengan looper atau komponen lain.', 'Ganti jarum, pastikan pemasangan benar, dan periksa kemungkinan kontak jarum dengan looper.', 'Matikan mesin dan lepaskan sumber listrik sebelum mengganti jarum atau memeriksa mekanisme jarum.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (26, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin terdengar kasar, bergerak tidak lancar, atau terdapat indikasi pelumasan yang tidak normal.', 'Pelumasan kurang, sistem pelumasan terganggu, atau terdapat bagian mekanis yang kotor atau mengalami keausan.', 'Periksa sistem pelumasan otomatis, gunakan oli yang sesuai, bersihkan area yang diperlukan, dan lakukan pemeriksaan mekanis jika diperlukan.', 'Matikan mesin sebelum melakukan pemeriksaan atau pembersihan bagian bergerak.', 'Data spesifikasi JUKI MO-6904S dan panduan pemeriksaan umum');
